#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::string s;
    std::cin >> s;

    int maxLen = 0, bracketTotal = 0;
    std::string outside, inside;

    for (int i = 0; i < n; i++) {
        if (s[i] == '(') {
            outside += "_";
            i++;
            while (i < n && s[i] != ')') {
                inside += s[i];
                i++;
            }
            inside += "_";
        } else {
            outside += s[i];
        }
    }

    std::vector<std::string> outsideParts;
    size_t start = 0, end;
    while ((end = outside.find('_', start)) != std::string::npos) {
        outsideParts.push_back(outside.substr(start, end - start));
        start = end + 1;
    }
    if (start < outside.size()) {
        outsideParts.push_back(outside.substr(start));
    }

    for (const auto& part : outsideParts) {
        maxLen = std::max(maxLen, (int)part.length());
    }

    std::vector<std::string> insideParts;
    start = 0;
    while ((end = inside.find('_', start)) != std::string::npos) {
        insideParts.push_back(inside.substr(start, end - start));
        start = end + 1;
    }
    if (start < inside.size()) {
        insideParts.push_back(inside.substr(start));
    }

    for (const auto& part : insideParts) {
        if (!part.empty()) {
            bracketTotal++;
        }
    }

    std::cout << maxLen << " " << bracketTotal << std::endl;
    return 0;
}
